//     enemigo.MoverHaciaJugador()
//     SI enRango ENTONCES enemigo.Atacar() FIN SI
// FIN MIENTRAS

// CÓDIGO C#:
while (enemigo.estaVivo && distancia < 5)
{
    enemigo.MoverHaciaJugador();
    if (enRango) enemigo.Atacar();
}

